-- Aprenda se Divertindo · 126 · Revisão das questões pelas leis de 2026
-- Corrige 18 questões que ficaram desatualizadas:
--   Lei 15.397/2026: furto simples 1 a 6 anos (delegado não arbitra mais fiança), repouso noturno aumenta da metade,
--     furto de veículo para outro estado 4 a 10 anos, latrocínio 24 a 30 anos, estelionato passa a ser de ação incondicionada.
--   Lei 15.358/2026: revogado o § 5º do art. 180 (perdão judicial na receptação culposa).
--   Lei 15.380/2026: audiência de retratação da Lei Maria da Penha só se a vítima pedir (explicações atualizadas).
-- Cole tudo no SQL Editor e clique em Run. Rodar de novo apenas atualiza.

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id": 256, "materia": "ppen", "nivel": 3, "enunciado": "A representação do ofendido será irretratável depois de:", "opcoes": ["Oferecida a denúncia", "Recebida a denúncia", "Instaurado o inquérito", "Proferida a sentença"], "explicacao": "Art. 25 do CPP. Na Lei Maria da Penha, a renúncia é em audiência perante o juiz, antes do recebimento da denúncia. Desde a Lei 15.380/2026, essa audiência só é marcada se a vítima manifestar expressamente o desejo de se retratar."}, {"id": 557, "materia": "pen", "nivel": 2, "enunciado": "O furto praticado durante o repouso noturno tem a pena aumentada de:", "opcoes": ["Metade", "1/3", "2/3", "1/6"], "explicacao": "Art. 155, § 1º, do CP, com a redação da Lei 15.397/2026. Antes, o aumento era de 1/3."}, {"id": 562, "materia": "pen", "nivel": 4, "enunciado": "Após a Lei 15.397/2026, a ação penal no estelionato é, em regra:", "opcoes": ["Pública incondicionada", "Pública condicionada à representação", "Privada", "Privada subsidiária"], "explicacao": "A Lei 15.397/2026 revogou o § 5º do art. 171, que, desde o Pacote Anticrime, exigia representação da vítima. A mudança não alcança fatos anteriores."}, {"id": 2548, "materia": "pen", "nivel": 1, "enunciado": "O furto praticado durante o repouso noturno tem a pena:", "opcoes": ["Aumentada da metade", "Aumentada de 1/3", "Dobrada", "Inalterada"], "explicacao": "Art. 155, § 1º, do CP, com a redação da Lei 15.397/2026. Antes, o aumento era de 1/3."}, {"id": 5452, "materia": "pen", "nivel": 3, "enunciado": "Fernanda enganou um idoso de 75 anos e obteve dele uma transferência por Pix. Nesse estelionato, a ação penal é:", "opcoes": ["Pública incondicionada", "Pública condicionada à representação", "Privada", "Privada personalíssima"], "explicacao": "Desde a Lei 15.397/2026, a ação no estelionato é incondicionada para qualquer vítima. Antes, a vítima maior de 70 anos já era uma das exceções à regra da representação."}, {"id": 5465, "materia": "ppen", "nivel": 2, "enunciado": "Investigado primário, sem violência, por furto simples (pena de 1 a 6 anos, desde a Lei 15.397/2026) e que confessou o crime pode receber:", "opcoes": ["Proposta de acordo de não persecução penal", "Transação penal obrigatória no juizado especial", "Perdão judicial automático", "Arquivamento obrigatório"], "explicacao": "A pena mínima (1 ano) é inferior a 4 anos e não houve violência ou grave ameaça (art. 28-A do CPP)."}, {"id": 5840, "materia": "pen", "nivel": 3, "enunciado": "O furto de veículo que é levado para outro estado ou para o exterior tem pena de:", "opcoes": ["Reclusão de 4 a 10 anos", "Reclusão de 1 a 4 anos", "Detenção de 6 meses a 2 anos", "Reclusão de 12 a 30 anos"], "explicacao": "Art. 155, § 5º, do CP, com a redação da Lei 15.397/2026. Antes, a pena era de 3 a 8 anos."}, {"id": 6044, "materia": "pen", "nivel": 1, "enunciado": "De madrugada, enquanto a família dormia, Rui entrou na casa e levou um notebook. A pena do furto:", "opcoes": ["Aumenta da metade, pelo repouso noturno", "Diminui pela metade, porque ninguém viu", "Não muda", "Vira multa"], "explicacao": "Art. 155, § 1º, do CP, com a redação da Lei 15.397/2026 (antes, o aumento era de 1/3)."}, {"id": 7363, "materia": "pen", "nivel": 3, "enunciado": "Furto de veículo automotor que venha a ser transportado para outro estado tem pena de:", "opcoes": ["Reclusão de 4 a 10 anos", "Reclusão de 3 a 8 anos", "Reclusão de 2 a 8 anos", "Detenção de 1 a 3 anos"], "explicacao": "Art. 155, § 5º, do CP, com a redação da Lei 15.397/2026. Antes, a pena era de 3 a 8 anos."}, {"id": 7437, "materia": "leg", "nivel": 4, "enunciado": "Na Lei Maria da Penha, a renúncia à representação, nas ações condicionadas, só é admitida:", "opcoes": ["Perante o juiz, em audiência especialmente designada, antes do recebimento da denúncia, ouvido o MP", "Na delegacia, por escrito", "Em qualquer momento, até a sentença", "Por mensagem ao promotor"], "explicacao": "Art. 16 da Lei 11.340/2006. Desde a Lei 15.380/2026, essa audiência só é marcada se a vítima manifestar expressamente o desejo de se retratar."}, {"id": 7628, "materia": "pen", "nivel": 2, "enunciado": "No estelionato, a ação penal voltou a ser pública incondicionada, em regra, com a:", "opcoes": ["Lei 15.397/2026, que revogou o § 5º do art. 171", "Lei 13.964/2019 (Pacote Anticrime)", "Lei 14.155/2021, que criou a fraude eletrônica", "Constituição Federal de 1988"], "explicacao": "O Pacote Anticrime (2019) tinha tornado o estelionato condicionado à representação; a Lei 15.397/2026 revogou essa regra."}, {"id": 7637, "materia": "pen", "nivel": 3, "enunciado": "A pena do latrocínio é de:", "opcoes": ["Reclusão de 24 a 30 anos e multa", "Reclusão de 20 a 30 anos e multa", "Reclusão de 12 a 30 anos", "Reclusão de 6 a 20 anos"], "explicacao": "Art. 157, § 3º, II, do CP, com a redação da Lei 15.397/2026. Antes, a pena era de 20 a 30 anos."}, {"id": 10066, "materia": "leg", "nivel": 1, "enunciado": "Pela Lei Maria da Penha, a vítima só pode renunciar à representação:", "opcoes": ["Perante o juiz, em audiência própria", "Na delegacia, em qualquer momento do inquérito", "Por escrito ao promotor", "Depois da sentença"], "explicacao": "Art. 16 da Lei 11.340/2006. Desde a Lei 15.380/2026, essa audiência só é marcada se a vítima manifestar expressamente o desejo de se retratar."}, {"id": 10078, "materia": "pen", "nivel": 1, "enunciado": "O furto praticado durante o repouso noturno tem a pena:", "opcoes": ["Aumentada da metade", "Aumentada de um terço", "Aplicada em dobro", "Igual à do furto simples"], "explicacao": "Art. 155, § 1º, do CP, com a redação da Lei 15.397/2026. Antes, o aumento era de um terço."}, {"id": 10416, "materia": "pen", "nivel": 4, "enunciado": "Desde a Lei 15.358/2026, que revogou o § 5º do art. 180 do CP, na receptação culposa praticada por réu primário:", "opcoes": ["Não há mais previsão de perdão judicial", "O juiz deve conceder perdão judicial obrigatoriamente", "A pena é sempre substituída por multa", "O fato deixa de ser crime"], "explicacao": "O § 5º do art. 180, que permitia o perdão judicial na receptação culposa e o privilégio na dolosa, foi revogado pela Lei 15.358/2026."}, {"id": 10419, "materia": "pen", "nivel": 4, "enunciado": "No latrocínio, a pena é de reclusão de:", "opcoes": ["24 a 30 anos e multa", "20 a 30 anos e multa", "12 a 30 anos e multa", "15 a 25 anos e multa"], "explicacao": "Art. 157, § 3º, II, do CP, com a redação da Lei 15.397/2026. Antes, a pena era de 20 a 30 anos."}, {"id": 10536, "materia": "ppen", "nivel": 1, "enunciado": "Um homem é preso em flagrante por furto simples, cuja pena passou a ser de 1 a 6 anos com a Lei 15.397/2026. Sobre a fiança:", "opcoes": ["Só o juiz pode arbitrá-la, porque a pena máxima passa de 4 anos", "O delegado pode arbitrá-la, porque o furto não tem violência", "Não cabe fiança em nenhum caso de furto", "O delegado deve soltar o preso sem fiança, por ser crime leve"], "explicacao": "Art. 322 do CPP: o delegado só arbitra fiança se a pena máxima não passar de 4 anos. Com o furto simples agora punido com 1 a 6 anos, a fiança é decidida pelo juiz."}, {"id": 10560, "materia": "pen", "nivel": 1, "enunciado": "Lucas entra numa casa de madrugada, enquanto a família dorme, e leva a TV. Além do furto, incide:", "opcoes": ["Aumento de pena pelo repouso noturno", "O privilégio, por ser réu primário e de bons antecedentes", "A forma culposa do furto", "A extinção da punibilidade"], "explicacao": "Art. 155, § 1º: aumento da metade, desde a Lei 15.397/2026 (antes, um terço)."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select id, left(enunciado, 70) as enunciado, opcoes ->> 0 as resposta_certa from public.questoes where id in (256, 557, 562, 2548, 5452, 5465, 5840, 6044, 7363, 7437, 7628, 7637, 10066, 10078, 10416, 10419, 10536, 10560) order by id;
select public.questoes_versao() as nova_versao;
